const ativosUnicos = [];
for (const r of ativos) {
  const chave = String(r.company_id);
  if (vistos.has(chave)) continue;
  vistos.add(chave);
  ativosUnicos.push(r);
}

const base = todas[0] || {};
const acessoGestao = Number(base.acesso_gestao_qtd || 0);

let caso;
if (!todas.length) {
  caso = 'NAO_ENCONTRADO';
} else if (ativosUnicos.length > 0) {
  caso = 'COM_VINCULO';
} else if (acessoGestao > 0) {
  // achou a pessoa, ela não tem vínculo ativo, MAS é gestor de alguma
  // empresa. Entra só para consultar.
  caso = 'SOMENTE_GESTOR';
} else if (rows.length > 0) {
  caso = 'SEM_VINCULO_ATIVO';
} else {
  // existe em [user], não tem employee nenhum e não é gestor de nada.
  // Não é colaborador da BMS: mesmo tratamento de não encontrado.
  caso = 'NAO_ENCONTRADO';
}

return [{
  json: {
    caso,
    total_vinculos: rows.length,
    total_ativos: ativosUnicos.length,
    multi_empresa: ativosUnicos.length > 1,
    vinculos_ativos: ativosUnicos.map((r) => ({
      employee_id: r.id_employee,
      company_id: r.company_id,
      empresa_nome: r.empresa_fantasia || r.empresa_nome || ('Empresa ' + r.company_id),
