    // CAMPOS NOVOS — o 7.1 lê estes dois
    pode_subir_atestado: caso === 'COM_VINCULO',
    acesso_gestao_qtd: acessoGestao,

    qtd_usuarios_no_telefone: 1,

    // dados pessoais são os mesmos em todos os vínculos (vêm de [user])
    id_user: base.id_user,
    name: base.name,
    cpf: base.cpf,
    birthdate: base.birthdate,
    email: base.email,
  },
}];

