={{ (() => {
  // ================= LISTA DE TELEFONES COM LOGOUT LIBERADO (FASE DE TESTE) =================
  // Edite APENAS esta lista. Formato: DDD + numero, com ou sem o 55. Ex.: '11999998888'
  const WHITELIST = [
    '1151962317',
    '21974662874',
    '11975881489'
  ];
  // ========================================================================================
  // normaliza para DDD+numero sem codigo de pais (mesma logica do 7.1; nao quebra DDD 51-55)
  const norm = (s) => {
    let x = (s ?? '').toString().replace(/\D/g, '');
    if (x.length >= 12 && x.startsWith('55')) x = x.slice(2);
    return x;
  };
  const phone = norm($('Edit Fields').first().json.phone);
  const liberado = WHITELIST.map(norm).filter(Boolean).includes(phone);
  if (!liberado) return false;

  const m = String($('Edit Fields').first().json.mensagem || '')
    .toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

  // comando de troca/logout
  const querTrocar =
    /\b(sair|logout|deslog)/.test(m) ||
    (/(troc|mud|alter|outro|outra|novo|nova)/.test(m) && /(funcion|colabor|pessoa|cadastr|conta|usuari|login|atend)/.test(m));
  return querTrocar;
